import json

def primes_upto(n):
    s = [True] * (n + 1)
    s[0] = s[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            for j in range(i * i, n + 1, i):
                s[j] = False
    return [i for i, v in enumerate(s) if v]

LIMIT = 300
ps = primes_upto(LIMIT)
found = []
checked = 0
for i, p in enumerate(ps):
    for q in ps[:i]:
        a, b = p + q, p - q
        num = a ** a * b ** b - 1
        den = a ** b * b ** a - 1
        checked += 1
        if den != 0 and num % den == 0:
            found.append((p, q))

answer = ", ".join(f"({p}, {q})" for p, q in found)
print(json.dumps({
    "final_answer": answer if found else "UNSUPPORTED",
    "evidence": {
        "search_limit_p": LIMIT,
        "pairs_checked": checked,
        "pairs_found": found,
    },
}))
